{"file_path":"/tmp/summarize_logs.py","content":"#!/usr/bin/env python3
"""Summarize severity counts from /app/logs into /app/summary.csv."""
import csv
import pathlib
import re

LOGS_DIR = pathlib.Path("/app/logs")
OUTPUT = pathlib.Path("/app/summary.csv")
REF_DATE = (2025, 8, 12)

import datetime
ref = datetime.date(*REF_DATE)

# Define date sets for each period (all including a given date).
today_dates = {ref}
last_7_dates = {ref - datetime.timedelta(days=i) for i in range(7)}
last_30_dates = {ref - datetime.timedelta(days=i) for i in range(30)}
month_to_date_dates = {
    datetime.date(ref.year, ref.month, day)
    for day in range(1, ref.day + 1)
}

periods = {
    "today": today_dates,
    "last_7_days": last_7_dates,
    "last_30_days": last_30_dates,
    "month_to_date": month_to_date_dates,
}

SEVERITIES = ("ERROR", "WARNING", "INFO")

# counts[period][severity]
counts = {period: {sev: 0 for sev in SEVERITIES} for period in periods}
counts["total"] = {sev: 0 for sev in SEVERITIES}

SEV_RE = re.compile(r"\[(ERROR|WARNING|INFO)\]")
FILENAME_RE = re.compile(r"^(\d{4})-(\d{2})-(\d{2})_")

for log_file in sorted(LOGS_DIR.glob("*.log")):
    m = FILENAME_RE.match(log_file.name)
    if not m:
        continue
    y, mo, d = (int(x) for x in m.groups())
    file_date = datetime.date(y, mo, d)

    # Determine which periods this file belongs to.
    in_periods = [p for p in periods if file_date in periods[p]]

    with log_file.open("r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            sev_match = SEV_RE.search(line)
            if not sev_match:
                continue
            sev = sev_match.group(1)
            counts["total"][sev] += 1
            for p in in_periods:
                counts[p][sev] += 1

# Write CSV in the required order.
with OUTPUT.open("w", newline="", encoding="utf-8") as fh:
    writer = csv.writer(fh)
    writer.writerow(["period", "severity", "count"])
    for period in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for sev in SEVERITIES:
            writer.writerow([period, sev, counts[period][sev]])

print(OUTPUT.read_text())
